  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, streamingResponse]);

  // Handle Token count updates from EventBus
  useEffect(() => {
    const unsub = eventBus.on('token-update', (data: any) => {
