        },
        body: JSON.stringify({
          prompt,
          image: sourceImage,
          aspectRatio,
          imageSize,
          model
        })
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Failed to process image request');
      }

      setGeneratedImage(data.image);
